const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const {esc,render:md}=window.YuewenFormat;
const state={view:'daily',region:'national',data:null,day:'',query:'',page:1,items:[],article:null,quote:'',paragraph:-1,anchorStart:null,anchorEnd:null,scope:'general',sources:[],special:null,folder:null,libraryKind:'all',library:null,notesKind:'all',managingNotes:false,selectedNoteArticles:new Set(),period:'day',metricsDay:'',purpose:'consultation'};
const labels={daily:'今日阅文',tasks:'代办文件',archive:'档案室',notes:'政研室',assistant:'办公室',metrics:'工作看板',sources:'来源与采集',settings:'主一设置'};
const kindNames={all:'全部',article:'原文材料',document:'研判文稿',minutes:'会议纪要',conversation:'讨论记录'};
const name=()=>state.data?.settings.secretary_name?.trim()||'秘书';
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});
const fmt=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}):'时间待核';
const pubfmt=a=>a.precision==='minute'?fmt(a.published):(a.published?a.published.slice(0,10):'日期待核');
const regionName=r=>r==='guangdong'?'广东增刊':'全国要闻';
const safeUrl=u=>/^https?:\/\//i.test(u||'')?esc(u):'#';
const draftKey=(id,field)=>'yuewen-draft-'+id+'-'+field;
function draft(id,field){try{return localStorage.getItem(draftKey(id,field))||''}catch{return ''}}
function saveDraft(id,field,value){try{if(value)localStorage.setItem(draftKey(id,field),value);else localStorage.removeItem(draftKey(id,field))}catch{}}
async function api(path,body){const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'操作失败');if(body!==undefined&&['/chat','/test-ai','/minutes','/settings'].includes(path))refreshUsage().catch(()=>{});return d;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4800)}
async function confirmAction(title,text){$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;const d=$('#confirm-dialog');d.returnValue='';d.showModal();return new Promise(resolve=>d.addEventListener('close',()=>resolve(d.returnValue==='ok'),{once:true}))}
function heading(title,action=''){return `<div class="page-heading"><h1>${esc(title)}</h1><div class="actions">${action}</div></div>`}
function empty(title){return `<div class="empty"><h2>${esc(title)}</h2></div>`}
function searchbar(){const hint=state.view==='notes'?'检索批注、摘录与心得':state.view==='archive'?'检索原文、纪要与文稿':'检索标题与原文';return `<form id="search-form" class="searchbar"><input class="search-input" id="search-input" name="q" aria-label="${hint}" placeholder="${hint}" value="${esc(state.query)}"><button class="btn primary">检索</button></form>`}
function stateTag(a){return a.state==='read'?'<span class="tag green">已阅</span>':a.state==='skipped'?'<span class="tag">已略过</span>':'<span class="tag red">待阅</span>'}
function listRow(a,i){return `<button type="button" class="document-card" data-open="${esc(a.id)}"><span class="doc-num">${String(i+1).padStart(2,'0')}</span><span class="card-body"><span class="doc-meta"><span class="tag ${a.tier===1?'red':''}">第${['','一','二','三'][a.tier]||'二'}层 · ${esc(a.kind)}</span><span>${esc(a.source)}</span><span>${pubfmt(a)}</span>${stateTag(a)}</span><span class="card-title">${esc(a.title)} <span class="tag annotation-count">批注 ${a.note_count||0} 处</span></span>${a.summary?`<span class="doc-summary">${window.YuewenFormat.inline(a.summary.replace(/\n/g,' '))}</span>`:''}<span class="doc-footer"><span>${a.minutes} 分钟 · ${esc(a.topics.join(' / '))}</span><span aria-hidden="true">↗</span></span></span></button>`}
function pagination(total){const pages=Math.ceil(total/12);return pages>1?`<div class="pagination"><button class="btn" data-page="${state.page-1}" ${state.page===1?'disabled':''}>上一页</button><span>${state.page} / ${pages}</span><button class="btn" data-page="${state.page+1}" ${state.page>=pages?'disabled':''}>下一页</button></div>`:''}
function list(items,grouped=false){const start=(state.page-1)*12;let previous='';return `<div class="document-list">${items.slice(start,start+12).map((a,i)=>{const group=a.score>=90?'重点呈阅':a.score>=70?'主要参阅':'参阅资料';const h=grouped&&previous!==group?`<h2 class="group-heading">${group}</h2>`:'';previous=group;return h+listRow(a,start+i)}).join('')}</div>${pagination(items.length)}`}
function editionTabs(items){return `<div class="tabs-row"><div class="tabs">${['national','guangdong'].map(r=>`<button class="tab ${state.region===r?'active':''}" data-region="${r}">${regionName(r)} <span>${items.filter(a=>a.region===r).length}</span></button>`).join('')}</div><span>约 ${items.filter(a=>a.region===state.region).reduce((s,a)=>s+a.minutes,0)} 分钟</span></div>`}
async function load(renderNow=true){state.data=await api('/dashboard'+(state.day?'?day='+state.day:''));$('#todo-count').textContent=state.data.pending;if(state.view==='daily')state.page=Math.min(state.page,Math.max(1,Math.ceil(state.data.articles.filter(a=>a.region===state.region).length/12)));if(renderNow)await render()}
async function render(){const view=state.view;$('#breadcrumb').textContent=labels[view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(state.special)return renderSpecial();if(view==='daily')renderDaily();if(view==='tasks'||view==='notes')await renderRecords();if(view==='archive')await renderLibrary();if(view==='assistant')await renderAssistant();if(view==='settings')renderSettings();if(view==='sources')await renderSources();if(view==='metrics')await renderMetrics()}
function renderDaily(){const d=state.data,e=d.edition,articles=d.articles,minutes=articles.reduce((n,a)=>n+a.minutes,0),completed=d.completed,total=d.total;
 const focus=articles.slice(0,2).map(a=>a.title).join('；');
 const brief=`<ol class="brief-points"><li><strong>重点事项。</strong>${esc(focus||'本期材料尚未准备。')}</li><li><strong>阅文安排。</strong>全国 ${d.edition_stats.national.total} 件，广东 ${d.edition_stats.guangdong.total} 件；剩余材料预计 ${minutes} 分钟。</li><li><strong>办理进度。</strong>本期已处理 ${completed} 篇；尚有 ${d.pending} 份代办文件。</li></ol>`;
 $('#content').innerHTML=heading('今日阅文',`<input aria-label="阅文日期" type="date" id="edition-date" class="date-input" value="${d.day}" max="${today()}"><button class="btn primary" data-action="collect" ${d.job.running?'disabled':''}>${d.job.running?'正在准备…':'更新本期材料'}</button>`)+`<section class="briefing"><div><div class="briefing-title"><h2>${esc(name())}汇报</h2>${e?.status==='partial'?'<button class="btn text" data-view="sources">采集报告 · 有缺项 ↗</button>':''}</div>${brief}${e?.briefing?`<details class="brief-detail"><summary>编选意见</summary><div class="formal">${md(e.briefing)}</div></details>`:''}</div><div class="brief-stats"><div class="stat-line"><strong>${articles.length}</strong><span>份待阅</span><span class="stat-divider"></span><strong>${minutes}</strong><span>分钟</span></div><div class="progress-track"><span style="width:${total?completed/total*100:0}%"></span></div><small>已处理 ${completed} / ${total}</small></div></section>`+(d.job.running?`<div class="notice loading" id="job-message">${esc(d.job.message)}</div>`:'')+editionTabs(articles)+(articles.some(a=>a.region===state.region)?list(articles.filter(a=>a.region===state.region),true):empty('本卷暂无材料'))+(articles.length?`<div class="actions summary-action"><button class="btn" data-action="daily-summary">请${esc(name())}作阅文小结</button></div>`:'');
}
function noteCard(n,compact=false){const styles={highlight:'高亮',underline:'下划线',strike:'删除线'};return `<article class="note-card">${n.quote?`<blockquote>${esc(n.quote)}</blockquote>`:''}${n.text?`<p>${esc(n.text)}</p>`:''}<div class="note-meta"><span class="tag red">${esc(n.kind)}</span> · ${fmt(n.created)}${n.title&&!compact?`<br><button class="btn text" data-open="${esc(n.article_id)}">${esc(n.title)}</button>`:''}</div><div class="note-actions">${styles[n.style]?`<button class="btn text" data-work="clear-note-style" data-id="${esc(n.id)}" aria-label="取消${styles[n.style]}">取消${styles[n.style]}</button>`:''}<button class="btn text" data-work="trash-note" data-id="${esc(n.id)}">删除批注</button></div></article>`}
async function renderRecords(){const view=state.view,query=state.query;const items=await api('/search?mode='+view+'&q='+encodeURIComponent(query));if(state.view!==view||state.query!==query)return;state.items=items;
 $('#content').innerHTML=heading(labels[view],view==='tasks'?'<button class="btn" data-action="clear-tasks">清空本卷代办</button>':`<button class="btn ${state.managingNotes?'selected':''}" data-work="manage-notes">${state.managingNotes?'完成管理':'管理'}</button><button class="btn text" data-work="notes-trash">回收站</button><button class="btn" data-action="research">请${esc(name())}协助研究</button>`)+searchbar();
 if(view==='notes'){const kinds=['all','批注','好词好句','存疑','不同看法','阅后心得'];const filtered=state.notesKind==='all'?items:items.filter(n=>n.kind===state.notesKind),groups=new Map();for(const n of filtered){if(!groups.has(n.article_id))groups.set(n.article_id,[]);groups.get(n.article_id).push(n)}const entries=[...groups];state.page=Math.min(state.page,Math.max(1,Math.ceil(entries.length/12)));$('#content').innerHTML+=`<p class="room-hint">这里保存你的批注、摘录与阅后心得；按原文归拢。客观材料在档案室。</p><div class="filter-tabs">${kinds.map(k=>`<button class="btn ${state.notesKind===k?'selected':''}" data-notes-kind="${k}">${k==='all'?'全部笔记':k}</button>`).join('')}</div>${state.managingNotes?`<div class="batch-bar"><label><input type="checkbox" id="select-research-page"> 选择本页文章</label><span id="research-selection-count">已选 ${state.selectedNoteArticles.size} 篇</span><button class="btn danger" data-work="batch-trash-notes">移入回收站</button></div>`:''}`+(entries.length?entries.slice((state.page-1)*12,state.page*12).map(([id,notes])=>`<section class="research-group"><header>${state.managingNotes?`<label><input type="checkbox" data-note-article="${esc(id)}" aria-label="选择${esc(notes[0].title)}" ${state.selectedNoteArticles.has(id)?'checked':''}></label>`:''}<div><small>${fmt(notes[0].published)} · ${notes.length} 条记录</small><h2><button class="research-title" data-open="${esc(id)}">${esc(notes[0].title)}</button></h2></div><button class="btn text" data-open="${esc(id)}">查看原文 ↗</button></header><div class="research-notes">${notes.map(n=>noteCard(n,true)).join('')}</div></section>`).join('')+pagination(entries.length):empty('暂无笔记'));return}
 const filtered=items.filter(a=>a.region===state.region);$('#content').innerHTML+=editionTabs(items)+(filtered.length?list(filtered,true):empty('本卷暂无代办'));
}

function resourceCard(r,i){const inner=r.resource_kind==='article'?listRow(r,i):`<button class="document-card" data-document="${esc(r.resource_id)}" data-kind="${r.resource_kind}"><span class="resource-icon" aria-hidden="true">${r.resource_kind==='minutes'?'纪':r.resource_kind==='conversation'?'议':'稿'}</span><span class="card-body"><span class="doc-meta"><span class="tag">${esc(r.kind||kindNames[r.resource_kind])}</span><span>${fmt(r.date)}</span>${r.message_count?`<span>${r.message_count} 条记录</span>`:''}</span><span class="card-title">${esc(r.title)}</span></span><span aria-hidden="true">↗</span></button>`;return `<div class="resource-box">${inner}<button class="btn text edit-file-button" data-work="edit-document" data-kind="${r.resource_kind}" data-id="${esc(r.resource_id)}">编辑</button><button class="btn text file-button" data-file="${esc(r.resource_id)}" data-kind="${r.resource_kind}" aria-label="将${esc(r.title)}归入专题">归入专题</button></div>`}
function showDialog(id,title,body,actions=''){const d=$(id);d.innerHTML=`<div class="document-header">${id==='#document-dialog'?'<button class="btn text" data-close="#document-dialog">← 返回</button>':''}<h2>${esc(title)}</h2><button class="btn text" data-close="${id}" aria-label="关闭">✕</button></div><div class="document-content">${body}</div>${actions?`<div class="document-actions">${actions}</div>`:''}`;if(!d.open)d.showModal()}


function messageCard(m){return `<article class="chat-message ${m.role==='user'?'user':''}"><div class="message-author">${m.role==='user'?'我':esc(m.speaker||name())+' · AI 建议'}${m.created?`<time>${fmt(m.created)}</time>`:''}<button class="btn text message-delete" data-work="delete-message" data-id="${esc(m.id)}" aria-label="删除这条${m.role==='user'?'提问':'答复'}">删除</button></div><div class="body formal">${md(m.content)}</div>${m.role==='assistant'&&m.citations?.length?`<div class="chat-citations">本答复引用${m.citations.map(c=>citationLink(c)).join('')}</div>`:''}</article>`}
async function renderMetrics(){const period=state.period,day=state.metricsDay||today(),m=await api('/metrics?period='+period+'&day='+day);if(state.view!=='metrics'||period!==state.period)return;const peak=Math.max(...m.series.map(s=>s.count),1);
 $('#content').innerHTML=heading('工作看板',`<input type="date" class="date-input" id="metrics-date" aria-label="统计日期" value="${day}"><button class="btn" data-action="save-summary">小结归档</button>`)+`<div class="filter-tabs">${Object.entries({day:'每日',week:'每周',month:'每月',quarter:'每季度'}).map(([k,v])=>`<button class="btn ${period===k?'selected':''}" data-period="${k}">${v}</button>`).join('')}<span class="muted period-range">${m.start} — ${m.end}</span></div><div class="metric-grid">${[['已阅材料',m.reads,'篇'],['批注与心得',m.notes,'条'],['议事提问',m.discussions,'次'],['归档文稿',m.documents,'份']].map(([label,n,unit])=>`<div class="metric"><span>${label}</span><strong>${n}<small>${unit}</small></strong></div>`).join('')}</div><div class="settings-grid"><section class="panel"><h2>办理记录</h2><div class="bar-chart" aria-label="每日阅读、批注和议事次数">${m.series.map(s=>`<div class="bar-column" title="${s.day}：${s.count} 次"><span style="height:${s.count/peak*100}%"></span></div>`).join('')}</div><div class="chart-labels"><span>${m.start}</span><span>${m.end}</span></div>${m.legacy_reads?`<p class="data-note">另有 ${m.legacy_reads} 篇历史已阅材料无办理时间，未计入本期。</p>`:''}</section><section class="panel"><h2>阅文议题</h2>${Object.keys(m.topics).length?Object.entries(m.topics).map(([t,n])=>`<div class="topic-row"><span>${esc(t)}</span><div class="progress-track"><span style="width:${n/Math.max(m.reads,1)*100}%"></span></div><strong>${n}</strong></div>`).join(''):'<p class="muted">本期暂无已阅记录</p>'}</section></div><section class="panel"><h2>工作小结</h2><div class="formal">${md(m.summary)}</div></section>`;
}

function bodyHTML(a){return (a.paragraphs||a.body.split('\n\n').map((text,index)=>({text,index}))).map(p=>`<p data-paragraph="${p.index}">${highlight(p.text,a.notes,p.index)}</p>`).join('')}
function clearSelection(){state.quote='';state.selectionParts=[];state.paragraph=-1;state.anchorStart=null;state.anchorEnd=null;if($('#selected-quote'))$('#selected-quote').innerHTML=''}

async function openArticle(id,options={}){const request=++readerRequest;const a=await api('/article?id='+encodeURIComponent(id));if(request!==readerRequest)return;if(!$('#reader').open)readerTrail=[];else if(state.article?.id!==id&&!options.back)readerTrail.push({id:state.article.id,main:$('.reader-main').scrollTop,aside:$('.reader-aside').scrollTop});state.article=a;clearSelection();const reflection=a.notes.filter(n=>n.kind==='阅后心得');
 $('#reader-content').innerHTML=`<div class="reader-header"><div class="reader-location">${readerTrail.length?'<button class="btn text" data-work="reader-back" aria-label="返回上一份文件">← 返回</button>':''}<span>${regionName(a.region)} / ${esc(a.kind)}</span></div><div class="actions"><button class="btn text" data-work="font-smaller" aria-label="减小字号">A−</button><button class="btn text" data-work="font-larger" aria-label="增大字号">A＋</button><button class="btn" data-work="reader-full">最大化</button><a class="btn" href="${safeUrl(a.url)}" target="_blank" rel="noopener noreferrer">原始网页 ↗</a><button class="btn text" data-action="close-reader" aria-label="关闭原文">✕</button></div></div><div class="reader-columns"><article class="reader-main"><div class="doc-meta">${esc(a.source)} · ${pubfmt(a)} · 约 ${a.minutes} 分钟</div><h1>${esc(a.title)}</h1><div class="doc-meta">${stateTag(a)}<span class="tag">${esc(a.topics.join(' / '))}</span></div>${a.summary?`<details class="reader-summary"><summary>内容提要</summary><div class="formal">${md(a.summary)}</div></details>`:''}<h2 class="original-heading">原文</h2><div class="article-text" id="article-text">${bodyHTML(a)}</div>${a.personal_edit?.edited?`<section class="personal-revision"><h2>个人修订稿</h2><div class="formal">${md(a.personal_edit.content)}</div></section>`:''}<button class="btn" data-work="edit-document" data-kind="article" data-id="${id}">编辑个人稿</button><section class="reflection-section"><h2>阅后心得</h2><div id="reflection-notes">${reflection.map(noteCard).join('')}</div><form id="reflection-form"><label class="sr-only" for="reflection-text">阅后心得</label><textarea id="reflection-text" name="text" placeholder="这篇材料带给你的理解、疑问或判断" required>${esc(draft(id,'reflection'))}</textarea><div class="actions"><button class="btn primary">保存心得</button><button type="button" class="btn" data-voice="reflection-text">开始转写</button></div></form></section><section class="analysis-section"><div class="section-heading"><h2>阅后研判</h2><button class="btn" data-action="article-summary">请${esc(name())}梳理</button></div><div id="analysis-answer" class="formal" aria-live="polite">${a.latest_analysis?md(a.latest_analysis.content):''}</div></section>${a.supplements.length?`<section class="related-section"><h2>补充材料</h2>${a.supplements.map(r=>`<button class="related-link" data-open="${r.id}">${esc(r.title)} <small>${esc(r.source)}</small></button>`).join('')}</section>`:''}${a.related.length?`<section class="related-section"><h2>相关档案</h2>${a.related.map(r=>`<button class="related-link" data-open="${r.id}">${esc(r.title)}<small>${fmt(r.published)} · ${esc(r.label)}</small></button>`).join('')}</section>`:''}</article><div id="reader-splitter" class="reader-splitter" role="separator" aria-label="调整正文与批注栏宽度" aria-orientation="vertical" tabindex="0"></div><aside class="reader-aside"><h3>朱批</h3><div id="selected-quote"></div><form id="note-form"><fieldset class="annotation-tools"><legend>标注样式</legend><input type="hidden" name="style" value="none"><div class="style-options">${[['highlight','高亮'],['underline','下划线'],['strike','删除线']].map(([k,v])=>`<button type="button" class="btn" data-work="apply-style" data-style="${k}">${v}</button>`).join('')}<button type="button" class="btn" data-work="clear-selection-style">取消所选标记</button></div><div class="color-options">${[['red','朱红'],['yellow','淡黄'],['green','浅绿'],['blue','浅蓝'],['purple','浅紫']].map(([k,v],i)=>`<label title="${v}"><input type="radio" name="color" value="${k}" aria-label="${v}" ${i===0?'checked':''}><span class="swatch color-${k}"></span></label>`).join('')}</div></fieldset><select name="kind" aria-label="批注类型"><option>批注</option><option>好词好句</option><option>存疑</option><option>不同看法</option></select><textarea name="text" id="note-text" aria-label="批注内容" placeholder="批注内容（可选）">${esc(draft(id,'note')||localStorage.getItem('draft-'+id)||'')}</textarea><div class="actions"><button class="btn primary">保存批注</button><button type="button" class="btn" data-voice="note-text">开始转写</button></div></form><div id="article-notes">${a.notes.filter(n=>n.kind!=='阅后心得').map(noteCard).join('')}</div><section class="side-card"><h3>询问${esc(name())}</h3><textarea id="article-question" aria-label="原文提问" placeholder="写下你的问题">${esc(draft(id,'ask'))}</textarea><div class="actions compose-actions"><button class="btn" data-voice="article-question">开始转写</button><button class="btn primary" data-action="ask-article">提问</button></div><label class="check-label"><input type="checkbox" id="article-web">允许外部检索</label><div id="article-answer" class="formal" aria-live="polite"></div><button class="btn text" data-action="article-history">历史问答</button></section><details><summary>文件办理</summary><div class="actions compose-actions"><button class="btn" data-article-action="hide">移出档案</button><button class="btn danger" data-article-action="delete">彻底删除</button><button class="btn" data-action="feedback">选稿反馈</button></div></details></aside></div><div class="reader-bottom"><span id="reader-note-count" class="muted">批注 ${a.notes.length} 处</span><div class="actions"><button class="btn" data-article-action="skip">略过</button><button class="btn" data-article-action="archive">存档</button><button class="btn primary" data-article-action="read">已阅并归档</button></div><div id="reader-grip" class="reader-grip" title="拖动调整阅读窗口大小" aria-hidden="true">◢</div></div>`;
 if(!$('#reader').open)$('#reader').showModal();$('.reader-main').scrollTop=0;$('.reader-aside').scrollTop=0;$('#article-text').addEventListener('mouseup',captureSelection);$('#article-text').addEventListener('keyup',captureSelection);wireReaderSizing();
}
async function refreshNotes(id){const a=await api('/article?id='+id);if(state.article?.id!==id)return;state.article=a;$('#article-notes').innerHTML=a.notes.filter(n=>n.kind!=='阅后心得').map(noteCard).join('');$('#reflection-notes').innerHTML=a.notes.filter(n=>n.kind==='阅后心得').map(noteCard).join('');$('#article-text').innerHTML=bodyHTML(a);$('#reader-note-count').textContent='批注 '+a.notes.length+' 处';await load(false)}
async function askArticle(summary=false){const aid=state.article.id,question=summary?'请结合这篇材料、我的阅后心得和批注，梳理要点，指出可核实的横向或纵向联系，并提出一个值得我思考的问题。区分原文事实、我的判断和你的建议。':$('#article-question').value;if(!question.trim())return toast('请先写下问题');const out=$(summary?'#analysis-answer':'#article-answer');out.textContent=name()+'正在查阅材料…';try{const r=await api('/chat',{question,article_id:aid,purpose:summary?'reading_summary':'consultation',web:!summary&&$('#article-web').checked});if(state.article?.id===aid&&out.isConnected){out.innerHTML=md(r.answer);if(!summary){saveDraft(aid,'ask','');$('#article-question').value=''}}if(r.external_error)toast(r.external_error)}catch(e){if(out.isConnected)out.textContent=e.message}}
function renderSettings(){const s=state.data.settings;$('#content').innerHTML=heading('主一设置','<button class="btn" data-work="runtime">原文与独立运行</button><button class="btn" data-action="logs">运行日志</button>')+`<form id="settings-form"><div class="settings-grid"><section class="panel"><h2>办公室设置</h2><div class="field"><label for="secretary_name">姓名</label><input id="secretary_name" name="secretary_name" value="${esc(s.secretary_name)}" maxlength="30" placeholder="未设置时使用“秘书”"></div><div class="field"><label for="user_title">对你的称呼</label><input id="user_title" name="user_title" value="${esc(s.user_title)}" maxlength="40"></div><div class="field"><label for="personality">语气与工作习惯</label><textarea id="personality" name="personality">${esc(s.personality)}</textarea></div><label class="check-label"><input name="auto_collect" type="checkbox" ${s.auto_collect?'checked':''}>自动准备每日材料</label></section><section class="panel"><h2>AI 接口</h2><div class="field"><label for="base_url">API 地址</label><input id="base_url" name="base_url" value="${esc(s.base_url)}" placeholder="https://…/v1"><small>支持本机或远程兼容接口。调用时会向所填服务发送所需文章、批注与问题。</small></div><div class="field"><label for="model">模型名称</label><input id="model" name="model" value="${esc(s.model)}"></div><div class="field"><label for="api_key">API 密钥</label><input id="api_key" name="api_key" type="password" autocomplete="new-password" placeholder="${s.has_key?'已保存；留空保持不变':'本机服务可留空；远程服务填写密钥'}"></div><div class="actions"><button type="button" class="btn" data-action="test-ai">测试已保存接口</button>${s.has_key?'<button type="button" class="btn text" data-action="clear-key">移除密钥</button>':''}</div></section></div><button class="btn primary">保存设置</button></form>`}
async function renderSources(){if(!state.sources.length)state.sources=await api('/sources');if(state.view!=='sources')return;const report=state.data.edition?.report||[];$('#content').innerHTML=heading('来源与采集','<button class="btn primary" data-action="collect">收集本期材料</button>')+`<section class="panel">${state.sources.map(s=>{const r=report.find(x=>x.id===s.id);return `<div class="source-row"><div><a href="${safeUrl(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a><small>${regionName(s.region)}</small></div><div>${esc(s.kind)}<small>${r?`候选 ${r.found||0} · 入选 ${r.included||0} · 失败 ${r.failed||0} · 日期待核 ${r.uncertain||0}${r.bounded?' · 已达候选上限':''}${r.error?' · '+esc(r.error):''}`:'暂无采集报告'}</small></div><span class="tag ${r?.status==='error'?'red':''}">${!s.enabled?'手动导入':r?.status==='error'?'采集失败':r?'已采集':'待采集'}</span></div>`}).join('')}<div class="actions compose-actions"><button class="btn" data-action="uncertain">日期待核材料</button></div><p class="data-note">每个来源最多扫描 45 条首页候选，未覆盖全部栏目；南方网未覆盖南方日报完整电子版。</p></section><section class="panel"><h2>导入官方原文</h2><form id="import-form"><div class="field"><label for="import-url">原文链接</label><input id="import-url" name="url" type="url" required placeholder="https://…"></div><details><summary>手动粘贴正文</summary><div class="field"><label for="import-title">标题</label><input id="import-title" name="title"></div><div class="field"><label for="import-date">发布时间</label><input id="import-date" name="published" type="datetime-local"></div><div class="field"><label for="import-body">正文</label><textarea id="import-body" name="body" rows="7"></textarea></div></details><button class="btn primary compose-actions">导入档案</button></form></section>`}
async function navigate(view){stopVoice();state.view=view;state.special=null;state.page=1;state.query='';if(view==='assistant'){state.scope='general';state.purpose='consultation'}await render();window.scrollTo(0,0)}
async function renderSpecial(){state.items=await api('/search?mode='+state.special);$('#content').innerHTML=heading(state.special==='uncertain'?'日期待核材料':'已移出档案',`<button class="btn" data-view="${state.special==='uncertain'?'sources':'archive'}">返回</button>`)+(state.items.length?list(state.items):empty('暂无材料'))}
async function articleAction(action){const a=state.article;if(action==='hide'&&!await confirmAction('移出档案？','文件及批注将从个人检索中隐藏，可从原日报或“已移出”恢复。'))return;if(action==='delete'&&!await confirmAction('彻底删除个人记录？','将删除正文副本、全部批注，以及引用过它的问答和衍生文稿，并更新相关会议纪要。不可撤销。'))return;await api('/article',{id:a.id,action,confirm:action==='delete'?a.id:undefined});if(action==='delete')for(const field of ['note','reflection','ask'])saveDraft(a.id,field,'');if(['read','skip','delete','hide'].includes(action))$('#reader').close();else await openArticle(a.id);await load();toast('办理完成')}

async function collectNow(){state.data.job=await api('/collect',{day:state.day||state.data.day});toast('开始收集本期材料');if(state.view==='daily')renderDaily();pollJob()}
let pollTimer;async function pollJob(){clearTimeout(pollTimer);try{const j=await api('/job');state.data.job=j;const el=$('#job-message');if(el)el.textContent=j.message;if(j.running)pollTimer=setTimeout(pollJob,2000);else{await load(state.view==='daily'||state.view==='sources');toast(j.error||j.message)}}catch(e){toast(e.message)}}

async function organize(){toast(name()+'正在拟定整理建议…');const p=await api('/organize',{});state.proposal=p;showDialog('#organize-dialog','专题整理建议',`<p class="data-note">本次检查 ${p.covered} / ${p.total} 篇原文。采用后新增专题归属，保留现有档案。</p>${p.groups.map(g=>`<section class="proposal-group"><h3>${esc(g.name)}</h3><p>${esc(g.reason)}</p><ul>${(g.articles||[]).map(a=>`<li>${esc(a.title)}</li>`).join('')}</ul><span class="tag">${g.article_ids.length} 篇材料</span></section>`).join('')}`,`<button class="btn" data-close="#organize-dialog">暂不采用</button><button class="btn primary" data-action="apply-organization">采用方案</button>`)}
async function onAction(action){
 if(action==='collect')return collectNow();if(action==='close-reader')return $('#reader').close();if(action==='clear-quote')return clearSelection();
 if(action==='clear-tasks'){if(await confirmAction('清空'+regionName(state.region)+'代办？','将标记为略过，保留原文与笔记。')){await api('/clear-tasks',{confirm:'clear',region:state.region});await load()}return}
 if(action==='test-ai'){toast('正在测试…');return toast((await api('/test-ai',{})).answer)}
 if(action==='clear-key'){if(await confirmAction('移除 API 密钥？','已有档案和笔记保留，移除后暂停 AI 调用。')){await api('/settings',{clear_key:true});await load()}return}
 if(action==='ask-article')return askArticle();if(action==='article-summary')return askArticle(true);
 if(action==='article-history'){state.scope=state.article.id;state.view='assistant';$('#reader').close();return render()}
 if(action==='general-chat'){state.scope='general';state.purpose='consultation';return renderAssistant()}
 if(action==='daily-summary')return prepareQuestion(`请回顾 ${state.data.day} 我已读并存档的材料和批注，整理主要议题、横向与纵向联系，区分事实和推断，保留我的不同看法，并提出一个思考问题。`,'daily_summary');
 if(action==='research')return prepareQuestion(state.query?`请根据档案中的“${state.query}”相关原文、批注和历史讨论，整理一份专题研究建议。`:'请根据我的档案和笔记，提出值得继续研究的议题，保留我的原有判断。','research');
 if(action==='today-minutes')return openDocument('minutes',today());
 if(action==='export'){const data=await api('/export'),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='主一档案-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);return}
 if(action==='uncertain'||action==='removed'){state.special=action;state.page=1;return renderSpecial()}
 if(action==='feedback'){const text=window.prompt('选稿反馈',state.article.feedback||'');if(text!==null){await api('/article',{id:state.article.id,action:'feedback',text});toast('已记录')}return}
 if(action==='new-folder'){const current=state.library?.folders.find(f=>f.id===state.folder);showDialog('#organize-dialog','新建专题',`<form id="folder-form"><div class="field"><label for="folder-name">专题名称</label><input id="folder-name" name="name" required maxlength="40"></div><div class="field"><label for="folder-parent">所属工作台</label><select id="folder-parent" name="parent_id"><option value="">一级专题</option>${state.library.folders.filter(f=>!f.parent_id).map(f=>`<option value="${f.id}" ${f.id===(current?.parent_id||current?.id)?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><button class="btn primary">创建</button></form>`);return}
 if(action==='organize')return organize();
 if(action==='apply-organization'){await api('/organize',{action:'apply',id:state.proposal.id});$('#organize-dialog').close();await renderLibrary();toast('专题已整理');return}
 if(action==='save-summary'){const r=await api('/period-summary',{period:state.period,day:state.metricsDay||today()});toast('小结已归档');return openDocument('document',r.id)}
 if(action==='logs'){const d=await api('/logs');return showDialog('#document-dialog','运行日志',`<pre class="log-output">${esc(d.lines.join('\n')||'暂无日志')}</pre>`)}
}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{
 if(b.dataset.work){b.disabled=true;try{return await workbenchAction(b.dataset.work,b)}finally{b.disabled=false}};
 if(b.dataset.view)return await navigate(b.dataset.view);
 if(b.dataset.open)return await openArticle(b.dataset.open);
 if(b.dataset.close)return $(b.dataset.close).close();
 if(b.dataset.document)return await openDocument(b.dataset.kind,b.dataset.document);
 if(b.dataset.voice)return await voice(b.dataset.voice);
 if(b.dataset.region){state.region=b.dataset.region;state.page=1;return await render()}
 if(b.dataset.page){state.page=Number(b.dataset.page);await render();window.scrollTo(0,0);return}
 if('folder' in b.dataset){state.folder=b.dataset.folder||null;state.page=1;await renderLibrary();window.scrollTo(0,0);return}
 if(b.dataset.libraryKind){state.libraryKind=b.dataset.libraryKind;state.page=1;return await renderLibrary()}
 if(b.dataset.notesKind){state.notesKind=b.dataset.notesKind;state.selectedNoteArticles.clear();state.page=1;return await renderRecords()}
 if(b.dataset.period){state.period=b.dataset.period;return await renderMetrics()}
 if(b.dataset.file){state.filing={id:b.dataset.file,kind:b.dataset.kind};showDialog('#organize-dialog','归入专题',`<form id="file-form"><div class="field"><label for="file-folder">目标专题</label><select id="file-folder" name="folder_id">${state.library.folders.map(f=>`<option value="${f.id}">${f.parent_id?esc(state.library.folders.find(p=>p.id===f.parent_id)?.name)+' / ':''}${esc(f.name)}</option>`).join('')}</select></div><button class="btn primary">归档</button></form>`);return}
 b.disabled=true;try{if(b.dataset.articleAction)return await articleAction(b.dataset.articleAction);if(b.dataset.minutes){toast(name()+'正在整理纪要…');await api('/minutes',{day:b.dataset.minutes});await openDocument('minutes',b.dataset.minutes);return}if(b.dataset.action)await onAction(b.dataset.action)}finally{b.disabled=false}
 }catch(err){toast(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='office-question')saveDraft(state.scope||'new','question',e.target.value);const fields={'note-text':'note','reflection-text':'reflection','article-question':'ask'};if(fields[e.target.id]&&state.article)saveDraft(state.article.id,fields[e.target.id],e.target.value)});
document.addEventListener('change',async e=>{try{if(e.target.id==='edition-date'){state.day=e.target.value;state.page=1;await load()}if(e.target.id==='metrics-date'){state.metricsDay=e.target.value;await renderMetrics()}}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{const f=e.target;if(['edit-document-form','batch-file-form'].includes(f.id)){e.preventDefault();return workbenchSubmit(f)}if(!['settings-form','import-form','note-form','reflection-form','search-form','chat-form','folder-form','file-form'].includes(f.id))return;e.preventDefault();const values=Object.fromEntries(new FormData(f)),button=f.querySelector('button:not([type=button])');if(button)button.disabled=true;try{
 if(f.id==='settings-form'){values.auto_collect=f.elements.auto_collect.checked;await api('/settings',values);await load();toast('设置已保存')}
 if(f.id==='import-form'){toast('正在读取原文…');const r=await api('/import',values);await load(false);await openArticle(r.id);toast('原文已归档')}
 if(f.id==='note-form'||f.id==='reflection-form'){const id=state.article.id,isReflection=f.id==='reflection-form';await api('/note',isReflection?{article_id:id,text:values.text,kind:'阅后心得',style:'none'}:{article_id:id,quote:state.quote,paragraph:state.paragraph,anchors:state.selectionParts||[],anchor_start:state.anchorStart,anchor_end:state.anchorEnd,...values});saveDraft(id,isReflection?'reflection':'note','');if(!isReflection)localStorage.removeItem('draft-'+id);if(state.article?.id===id){f.querySelector('textarea').value='';if(!isReflection)clearSelection();await refreshNotes(id)}toast(isReflection?'心得已保存':'批注已保存')}
 if(f.id==='search-form'){state.query=values.q||'';if(state.view==='notes')state.selectedNoteArticles.clear();state.page=1;await render()}
 if(f.id==='chat-form'){if(!state.scope){const room=await api('/conversations',{title:values.question.slice(0,45)});state.scope=room.id}const scope=state.scope;button.textContent='正在查阅…';const r=await api('/chat',{...values,web:f.elements.web.checked,conversation_id:scope,purpose:state.purpose});saveDraft(scope,'question','');saveDraft('new','question','');if(state.view==='assistant'&&state.scope===scope)await renderAssistant();if(r.external_error)toast(r.external_error)}
 if(f.id==='folder-form'){await api('/dossiers',{name:values.name,parent_id:values.parent_id||null});$('#organize-dialog').close();await renderLibrary()}
 if(f.id==='file-form'){await api('/file-resource',{...state.filing,folder_id:values.folder_id});$('#organize-dialog').close();await renderLibrary();toast('已归入专题')}
 }catch(err){toast(err.message);if(f.id==='chat-form'&&button)button.textContent='交给'+name()}finally{if(button)button.disabled=false}});
$('#reader').addEventListener('close',()=>{readerTrail=[];++readerRequest;stopVoice();clearSelection();load().catch(e=>toast(e.message))});
function clockTick(){$('#clock').textContent=new Date().toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}clockTick();setInterval(clockTick,30000);
window.addEventListener('error',()=>api('/client-error',{code:'runtime_error'}).catch(()=>{}));window.addEventListener('unhandledrejection',()=>api('/client-error',{code:'unhandled_rejection'}).catch(()=>{}));
async function boot(){try{await load();refreshUsage().catch(()=>{});if(state.data.job.running)pollJob()}catch(e){$('#content').innerHTML=heading('暂时无法打开档案')+`<div class="notice">${esc(e.message)}</div>`}}boot();
const mc=document.modelContext;if(mc?.registerTool){try{Promise.resolve(mc.registerTool({name:'search_personal_archive',title:'检索主一档案',description:'只读检索档案室中的原文、会议纪要和文稿，并展示结果。用户批注与心得请在政研室检索。',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},async execute(input){if(typeof input?.query!=='string')throw Error('query 必须是文本');state.view='archive';state.special=null;state.folder=null;state.libraryKind='all';state.query=input.query;state.page=1;await render();return state.items.map(a=>({id:a.resource_id,title:a.title,kind:a.resource_kind}))}})).catch(()=>{})}catch{}}
